import { useEffect, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { Truck, Leaf as LeafIcon, Hand } from "lucide-react";
import { QuantityStepper } from "../components/ui/QuantityStepper";
import { Button } from "../components/ui/Button";
import { SubPageHeader } from "../components/ui/SubPageHeader";
import { ProduceBadge } from "../components/product";
import { getProducts } from "../data/products";
import { useProduct } from "../hooks/useProduct";
import { useAddToCart } from "../hooks/useAddToCart";
import useDocumentTitle from "../hooks/useDocumentTitle";
import { ROUTES } from "../config/navigation";
import { COPY } from "../config/copy";
import { formatINR } from "../config/constants";

const FACTS = [
  { icon: LeafIcon, label: COPY.farmFresh },
  { icon: Hand, label: COPY.handPicked },
  { icon: Truck, label: COPY.sameDayDelivery },
];

export default function ProductDetail() {
  const { slug } = useParams();
  const navigate = useNavigate();
  const [qty, setQty] = useState(1);
  const [selectedVariant, setSelectedVariant] = useState(null);
  const [related, setRelated] = useState([]);
  const addToCart = useAddToCart();

  const { product, loading, error } = useProduct(slug);

  useEffect(() => {
    if (product?.variants) {
      const active = product.variants.filter((v) => v.status === "active");
      if (active.length > 0) setSelectedVariant(active[0]);
    }
  }, [product]);

  useEffect(() => {
    if (product?.category?.slug) {
      getProducts({ category: product.category.slug, perPage: 5 }).then(
        ({ products }) => {
          setRelated(products.filter((r) => r.slug !== slug).slice(0, 4));
        },
      );
    }
  }, [product, slug]);

  useDocumentTitle(product ? product.name : "Product");

  if (loading) {
    return (
      <div className="py-20 text-center animate-pulse space-y-4">
        <div className="h-64 md:h-72 bg-leaf-100 rounded-card mx-auto max-w-md" />
        <div className="h-6 bg-leaf-100 rounded w-1/3 mx-auto" />
        <div className="h-4 bg-leaf-100 rounded w-1/2 mx-auto" />
      </div>
    );
  }

  if (error || !product) {
    return (
      <div className="text-center py-20 text-muted">
        <p className="mb-3">{COPY.productNotFound}</p>
        <Button variant="outline" onClick={() => navigate(ROUTES.home)}>
          {COPY.backToShop}
        </Button>
      </div>
    );
  }

  const activeVariants =
    product.variants?.filter((v) => v.status === "active") ?? [];
  const price = selectedVariant ? parseFloat(selectedVariant.current_price) : 0;
  const unit = selectedVariant?.display_label ?? "";
  const tagName = product.tags?.[0]?.name;

  const handleAdd = () => {
    if (!selectedVariant) return;
    addToCart(
      {
        slug: product.slug,
        name: product.name,
        image_url: product.image_url,
        price,
        variant: selectedVariant,
      },
      qty,
    );
  };

  return (
    <div className="pb-6">
      <SubPageHeader title={product.name} backTo={ROUTES.shop} />

      <div className="relative -mx-4 -mt-4 md:mx-0 md:mt-0 md:rounded-card overflow-hidden h-64 md:h-72 bg-leaf-100/60">
        {product.image_url ? (
          <img
            src={product.image_url}
            alt={product.name}
            className="w-full h-full object-contain"
          />
        ) : (
          <div className="w-full h-full flex items-center justify-center">
            <svg
              xmlns="http://www.w3.org/2000/svg"
              width="40"
              height="40"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.5"
              className="text-leaf-400"
            >
              <path d="M12 2L2 7l10 5 10-5-10-5zM2 17l10 5 10-5M2 12l10 5 10-5" />
            </svg>
          </div>
        )}
        {tagName && (
          <ProduceBadge
            label={tagName}
            tone="leaf"
            size={60}
            className="absolute bottom-3 left-4"
          />
        )}
      </div>

      <div className="mt-5">
        <p className="type-eyebrow mb-1">{product.category?.name ?? ""}</p>
        <h1 className="type-hero mb-1">{product.name}</h1>
        <p className="type-caption mb-3">{unit}</p>

        <div className="flex items-center gap-3 mb-4">
          <span className="type-price-lg">{formatINR(price)}</span>
        </div>

        {activeVariants.length > 1 && (
          <div className="flex flex-wrap gap-2 mb-4">
            {activeVariants.map((v) => (
              <button
                key={v.id}
                onClick={() => setSelectedVariant(v)}
                className={`text-sm px-3 py-1 rounded-pill border ${
                  selectedVariant?.id === v.id
                    ? "bg-leaf-500 text-white border-leaf-500"
                    : "bg-surface border-border text-body"
                }`}
              >
                {v.display_label} – ₹{parseFloat(v.current_price)}
              </button>
            ))}
          </div>
        )}

        <div className="grid grid-cols-3 gap-2 mb-6">
          {FACTS.map(({ icon: Icon, label }) => (
            <div
              key={label}
              className="flex flex-col items-center gap-1.5 bg-leaf-100 rounded-card py-3"
            >
              <Icon size={18} className="text-leaf-700" />
              <span className="text-[11px] font-medium text-leaf-900">
                {label}
              </span>
            </div>
          ))}
        </div>

        <div className="flex items-center gap-4 mb-2">
          <span className="text-sm font-medium text-ink">
            {COPY.quantityLabel}
          </span>
          <QuantityStepper value={qty} onChange={setQty} min={1} />
        </div>
      </div>

      <div className="fixed bottom-[var(--bottomnav-height)] md:bottom-0 inset-x-0 z-30 bg-surface/95 backdrop-blur border-t border-border p-3 safe-bottom">
        <div className="max-w-6xl mx-auto">
          {activeVariants.length > 0 ? (
            <Button className="w-full py-3" onClick={handleAdd}>
              Add {qty > 1 ? `${qty} ` : ""}to cart · {formatINR(price * qty)}
            </Button>
          ) : (
            <div className="text-center text-sm text-tomato-600 bg-tomato-100 rounded-btn py-3">
              Currently unavailable
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import { useEffect, useState } from "react";
import { useSearchParams } from "react-router-dom";
import { Search, SlidersHorizontal, Sprout } from "lucide-react";
import { getCategories } from "../data/categories";
import { useProducts } from "../hooks/useProducts";
import ProductCard from "../components/product/ProductCard";
import Hero from "../components/hero/Hero";
import useDocumentTitle from "../hooks/useDocumentTitle";
import { LoadingSkeleton } from "../components/ui/LoadingSkeleton";
import { COPY, tpl } from "../config/copy";

export default function Products() {
  const [searchParams] = useSearchParams();
  const initialSearch = searchParams.get("search") || "";
  const [query, setQuery] = useState(initialSearch);

  const [categories, setCategories] = useState([]);
  const [catError, setCatError] = useState(null);

  const [selectedParent, setSelectedParent] = useState("");
  const [selectedSub, setSelectedSub] = useState("");

  const { products, loading, error } = useProducts({
    search: query,
    category: selectedParent,
    subcategory: selectedSub,
  });

  useDocumentTitle("Shop");

  useEffect(() => {
    getCategories()
      .then(setCategories)
      .catch(() => setCatError(COPY.productsLoadingError));
  }, []);

  useEffect(() => {
    setQuery(searchParams.get("search") || "");
  }, [searchParams]);

  // Derive parent and child categories
  const parentCategories = categories.filter((c) => !c.parent_id);
  const selectedParentId = parentCategories.find(
    (c) => c.slug === selectedParent,
  )?.id;
  const subCategories = categories.filter(
    (c) => c.parent_id === selectedParentId,
  );

  const availableProducts = products.filter((product) =>
    product.variants?.some((v) => v.status === "active"),
  );

  const handleParentClick = (slug) => {
    setSelectedParent(slug === selectedParent ? "" : slug);
    setSelectedSub(""); // reset sub when parent changes
  };

  return (
    <div>
      <Hero />

      {/* Mobile search */}
      <div className="md:hidden flex items-center gap-2 bg-surface rounded-pill px-3.5 py-2.5 border border-border mb-4">
        <Search size={17} className="text-muted" />
        <input
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder={COPY.searchPlaceholder}
          className="bg-transparent text-sm outline-none placeholder:text-muted w-full"
        />
        <SlidersHorizontal size={16} className="text-muted shrink-0" />
      </div>

      {/* Parent categories */}
      <div className="flex gap-2 overflow-x-auto no-scrollbar mb-3">
        <button
          onClick={() => handleParentClick("")}
          className={`shrink-0 text-sm font-medium px-4 py-1.5 rounded-pill border ${
            selectedParent === ""
              ? "bg-leaf-500 border-leaf-500 text-white"
              : "bg-surface border-border text-body hover:border-leaf-400"
          }`}
        >
          {COPY.categoryAll}
        </button>
        {parentCategories.map((c) => (
          <button
            key={c.slug}
            onClick={() => handleParentClick(c.slug)}
            className={`shrink-0 text-sm font-medium px-4 py-1.5 rounded-pill border transition-colors ${
              selectedParent === c.slug
                ? "bg-leaf-500 border-leaf-500 text-white"
                : "bg-surface border-border text-body hover:border-leaf-400"
            }`}
          >
            {c.name}
          </button>
        ))}
      </div>

      {/* Subcategories (only when parent selected and has children) */}
      {selectedParent && subCategories.length > 0 && (
        <div className="flex gap-2 overflow-x-auto no-scrollbar mb-4">
          <button
            onClick={() => setSelectedSub("")}
            className={`shrink-0 text-xs font-medium px-3 py-1 rounded-pill border ${
              selectedSub === ""
                ? "bg-leaf-100 border-leaf-500 text-leaf-700"
                : "bg-surface border-border text-body hover:border-leaf-400"
            }`}
          >
            All
          </button>
          {subCategories.map((c) => (
            <button
              key={c.slug}
              onClick={() => setSelectedSub(c.slug)}
              className={`shrink-0 text-xs font-medium px-3 py-1 rounded-pill border transition-colors ${
                selectedSub === c.slug
                  ? "bg-leaf-100 border-leaf-500 text-leaf-700"
                  : "bg-surface border-border text-body hover:border-leaf-400"
              }`}
            >
              {c.name}
            </button>
          ))}
        </div>
      )}

      {catError && <p className="text-sm text-red-500 mb-3">{catError}</p>}

      {/* Product grid states */}
      {loading ? (
        <LoadingSkeleton variant="product-card" />
      ) : error ? (
        <div className="text-center py-16 text-muted">
          <p className="font-medium text-body">{error}</p>
          <button
            onClick={() => window.location.reload()}
            className="text-leaf-700 text-sm mt-2 underline"
          >
            {COPY.reloadPage}
          </button>
        </div>
      ) : availableProducts.length > 0 ? (
        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-3 md:gap-4">
          {availableProducts.map((product) => (
            <ProductCard key={product.slug} product={product} />
          ))}
        </div>
      ) : (
        <div className="flex flex-col items-center text-center py-16 text-muted">
          <Sprout size={32} className="mb-3 text-leaf-400" />
          <p className="font-medium text-body">
            {tpl(COPY.noProductsMatch, { query })}
          </p>
          <p className="text-sm">{COPY.noProductsHint}</p>
        </div>
      )}
    </div>
  );
}

import { useState } from "react";
import { useNavigate } from "react-router-dom";
import {
  ChevronRight,
  HelpCircle,
  LogOut,
  MapPin,
  Package,
  Pencil,
  Wallet,
  Bell,
} from "lucide-react";
import toast from "react-hot-toast";
import { useAuth } from "../context/AuthContext";
import { ROUTES } from "../config/navigation";
import { COPY } from "../config/copy";

const MENU_ICONS = {
  orders: Package,
  addresses: MapPin,
  payment: Wallet,
  notifications: Bell,
  help: HelpCircle,
};

export default function Profile() {
  const { user, logout, updateProfile } = useAuth();
  const navigate = useNavigate();

  // Separate editing states for header and address card
  const [profileEditing, setProfileEditing] = useState(false);
  const [addressEditing, setAddressEditing] = useState(false);

  const [address, setAddress] = useState({
    name: user?.name || "",
    address_line1: user?.address_line1 || "",
    address_line2: user?.address_line2 || "",
    landmark: user?.landmark || "",
    pincode: user?.pincode || "",
  });
  const [saving, setSaving] = useState(false);

  const initials = (user?.name || "G")
    .split(" ")
    .map((s) => s[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();

  const handleLogout = () => {
    logout();
    navigate(ROUTES.login);
  };

  const handleSaveAddress = async () => {
    if (!address.name.trim()) {
      toast.error("Name is required.");
      return;
    }
    if (!address.address_line1.trim() || !address.pincode.trim()) {
      toast.error("Address and pincode are required.");
      return;
    }

    setSaving(true);
    try {
      await updateProfile(address);
      toast.success("Address updated.");
      setAddressEditing(false);
    } catch (err) {
      toast.error(err.response?.data?.message || "Failed to update address");
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="pb-6">
      {/* Profile header – clicking toggles profile editing */}
      <div
        onClick={() => setProfileEditing((e) => !e)}
        role="button"
        tabIndex={0}
        onKeyDown={(e) => {
          if (e.key === "Enter" || e.key === " ") {
            e.preventDefault();
            setProfileEditing((e) => !e);
          }
        }}
        className="flex items-center gap-4 mb-6 cursor-pointer select-none"
      >
        <div className="relative w-16 h-16 rounded-full bg-leaf-500 text-white flex items-center justify-center font-display text-xl font-semibold shrink-0">
          {initials}
        </div>
        <div className="min-w-0">
          <h1 className="type-hero truncate">{user?.name || "Guest"}</h1>
          <p className="type-caption truncate">
            {user?.phone || COPY.notSignedIn}
          </p>
        </div>
        <button
          onClick={(e) => {
            e.stopPropagation();
            setProfileEditing((e) => !e);
          }}
          aria-label={COPY.editProfileAria}
          className="ml-auto w-9 h-9 rounded-full bg-leaf-100 flex items-center justify-center shrink-0 transition-transform active:scale-90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-leaf-300"
        >
          <Pencil size={15} className="text-leaf-700" />
        </button>
      </div>

      {/* Address card */}
      <div className="bg-surface rounded-card shadow-card p-4 mb-6">
        <div className="flex items-center justify-between mb-3">
          <h2 className="type-section">{COPY.addressTitle}</h2>
          {!addressEditing && (
            <button
              onClick={() => setAddressEditing(true)}
              className="text-sm text-leaf-700 flex items-center gap-1"
            >
              <Pencil size={13} />
              {COPY.editAddress}
            </button>
          )}
        </div>

        {addressEditing ? (
          <div className="space-y-3">
            <input
              value={address.name}
              onChange={(e) => setAddress({ ...address, name: e.target.value })}
              placeholder="Full name"
              className="w-full border border-border rounded-btn px-3 py-2.5 text-sm outline-none placeholder:text-muted"
            />
            <input
              value={address.address_line1}
              onChange={(e) =>
                setAddress({ ...address, address_line1: e.target.value })
              }
              placeholder={COPY.addressLine1Placeholder}
              className="w-full border border-border rounded-btn px-3 py-2.5 text-sm outline-none placeholder:text-muted"
            />
            <input
              value={address.address_line2}
              onChange={(e) =>
                setAddress({ ...address, address_line2: e.target.value })
              }
              placeholder={COPY.addressLine2Placeholder}
              className="w-full border border-border rounded-btn px-3 py-2.5 text-sm outline-none placeholder:text-muted"
            />
            <input
              value={address.landmark}
              onChange={(e) =>
                setAddress({ ...address, landmark: e.target.value })
              }
              placeholder={COPY.landmarkPlaceholder}
              className="w-full border border-border rounded-btn px-3 py-2.5 text-sm outline-none placeholder:text-muted"
            />
            <input
              value={address.pincode}
              onChange={(e) =>
                setAddress({ ...address, pincode: e.target.value })
              }
              placeholder={COPY.pincodePlaceholder}
              type="tel"
              className="w-full border border-border rounded-btn px-3 py-2.5 text-sm outline-none placeholder:text-muted"
            />

            <div className="flex gap-2 pt-1">
              <button
                type="button"
                onClick={() => setAddressEditing(false)}
                className="flex-1 py-2.5 rounded-btn border border-border text-body text-sm"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={handleSaveAddress}
                disabled={saving}
                className="flex-1 py-2.5 rounded-btn bg-leaf-500 text-white text-sm font-medium"
              >
                {saving ? "Saving…" : COPY.saveAddress}
              </button>
            </div>
          </div>
        ) : (
          <div className="text-sm text-body">
            <p className="font-medium text-ink">{user?.name || "—"}</p>
            <p>{user?.address_line1 || "No address saved"}</p>
            {user?.address_line2 && <p>{user.address_line2}</p>}
            {user?.landmark && <p>{user.landmark}</p>}
            <p className="font-medium">{user?.pincode || ""}</p>
          </div>
        )}
      </div>

      <div className="bg-surface rounded-card shadow-card divide-y divide-border overflow-hidden mb-6">
        {COPY.menuItems.map(({ label, key }) => {
          const Icon = MENU_ICONS[key];
          return (
            <button
              key={key}
              onClick={() => {
                if (key === "orders") {
                  navigate(ROUTES.orders);
                } else if (key === "addresses") {
                  setAddressEditing(true);
                } else {
                  toast(COPY.menuNotWired.replace("{{label}}", label));
                }
              }}
              className="w-full flex items-center gap-3 px-4 py-3.5 text-left hover:bg-page transition-colors"
            >
              {Icon && <Icon size={18} className="text-leaf-700 shrink-0" />}
              <span className="type-name">{label}</span>
              <ChevronRight size={16} className="ml-auto text-muted shrink-0" />
            </button>
          );
        })}
      </div>

      <button
        onClick={handleLogout}
        className="w-full flex items-center justify-center gap-2 text-tomato-600 font-medium py-3"
      >
        <LogOut size={17} />
        {COPY.logoutLabel}
      </button>
    </div>
  );
}
